/**
 * gardens.js — a kitchen garden's beds, walks and what grows in them (T-3407).
 *
 * WHY. The owner, 2026-11-06, standing at stop 9 of the Fort Dearborn jaunt, which reads
 * Quaife's "melons and other small fruit and vegetables" over the commanding officer's
 * garden: *"you describe this awesome garden for 1812 but nothing is in the garden"*. The
 * paling was built (T-2062) and the plot inside it was the bare sward.
 *
 * WHAT IT DRAWS, from `data/gardens/<scene>.json` (generated by tools/plant_gardens.py from
 * the garden's own record and Whistler's draught, which its --check holds):
 *
 *   the walks   trodden earth over the whole plot inside the paling;
 *   the beds    tilled loam, each bed the draught's clipped-corner box, crowned a hand high
 *               and drawn in its rows;
 *   the crops   every plant GROWN here from a few procedural parts (a leaf atlas painted on
 *               a canvas at load, stalks, vines, poles and fruit), a few variants of each
 *               crop, two levels by distance, all in two BatchedMeshes: one draw for the
 *               leaves and one for the solid parts, each plant one instance.
 *
 * WHAT IS EVIDENCE. The beds and walks are the draught's (inferred: its scale is read, not
 * stated in words). Melons and small fruit are Quaife's (attested of the garden in
 * Whistler's and Cooper's years). Every other crop, every plant's place and every leaf is
 * reconstructed from the period's kitchen-garden calendar for August (M'Mahon), claimed at
 * docs/LIBERTIES.md L-t3407-officers-garden. Each plant carries its bed's grade, so the
 * confidence view shows which is which, and Inspect on a bed says so in words.
 *
 * WHAT IT COSTS. The atlas is one 1024 x 512 canvas (about 2.8 MB on the GPU with its
 * mips). The templates are a few hundred triangles near and a few dozen far, so the whole
 * garden is about one draw call per material and well under a megabyte of geometry. A
 * phone draws the near level only within NEAR_M.light and the rest at the far level.
 */

import * as THREE from 'three';

const CONF = { attested: 0, inferred: 0.5, reconstructed: 1 };

/** Rings, metres from the eye: a plant nearer than `near` is drawn at its near level,
 *  nearer than `mid` at its mid level, nearer than `far` at its far level (a few cards and
 *  its fruit), and beyond that not at all. */
const LEVELS = {
  full: { near: 20, mid: 55, far: 450 },
  balanced: { near: 15, mid: 45, far: 380 },
  light: { near: 8, mid: 30, far: 280 },
};
const LODS = ['near', 'mid', 'far'];
const STEP_M = 2.5;
/** Shadows: the near set casts in full and balanced; a phone casts none. */
const CAST = { full: true, balanced: true, light: false };

const SOIL_LIFT = { walk: 0.03, bed: 0.05, crown: 0.07 };
const CELL_M = 0.6;

/* -------------------------------------------------------------------------- */
/* a little deterministic randomness                                           */
/* -------------------------------------------------------------------------- */

function rng(seed) {
  let a = (seed >>> 0) || 1;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function strSeed(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i += 1) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

/* -------------------------------------------------------------------------- */
/* the leaf atlas: 4 x 2 tiles of 256 px, painted once                         */
/* -------------------------------------------------------------------------- */

const TILE = 256;
const GRID = [4, 2];
/** Which tile each leaf habit is painted in. */
export const LEAF = { strap: 0, cucurbit: 1, bean: 2, cabbage: 3, beet: 4, fern: 5, potato: 6, berry: 7 };

function hsl(h, s, l, a = 1) { return `hsla(${h},${s}%,${l}%,${a})`; }

/** A leaf outline from base (0) to tip (1): half-width at t for each habit. */
function halfWidth(kind, t, r) {
  const s = Math.sin(Math.PI * Math.min(1, Math.max(0, t)));
  switch (kind) {
    case 'strap': return 0.5 * Math.pow(Math.sin(Math.PI * Math.min(1, t * 0.92 + 0.04)), 0.45) * (1 - t * 0.35);
    case 'bean': return 0.5 * Math.pow(s, 0.8) * (t < 0.35 ? 1.08 : 1 - (t - 0.35) * 0.45);
    case 'beet': return 0.5 * Math.pow(s, 0.65) * (1 + 0.05 * Math.sin(t * 40 + r));
    case 'cabbage': return 0.5 * Math.pow(Math.sin(Math.PI * (0.08 + t * 0.92)), 0.5) * (1 + 0.04 * Math.sin(t * 33 + r));
    default: return 0.5 * s;
  }
}

/** Paint a simple-bladed leaf (strap, bean, beet, cabbage) into the tile at (ox, oy). */
function paintBlade(ctx, ox, oy, kind, base, rib, vein, seed) {
  const r = rng(seed);
  const W = TILE, H = TILE;
  const wide = { strap: 0.30, bean: 0.78, beet: 0.72, cabbage: 0.96 }[kind];
  const cx = ox + W / 2;
  const y0 = oy + H - 4, y1 = oy + 4;
  const pts = [];
  const N = 48;
  for (let i = 0; i <= N; i += 1) {
    const t = i / N;
    pts.push([t, halfWidth(kind, t, r() * 6) * W * wide]);
  }
  const at = (t, side) => {
    const hw = pts[Math.round(t * N)][1];
    return [cx + side * hw, y0 + (y1 - y0) * t];
  };
  ctx.save();
  ctx.beginPath();
  for (let i = 0; i <= N; i += 1) { const [x, y] = at(i / N, -1); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
  for (let i = N; i >= 0; i -= 1) { const [x, y] = at(i / N, 1); ctx.lineTo(x, y); }
  ctx.closePath();
  const g = ctx.createLinearGradient(cx - W * wide / 2, 0, cx + W * wide / 2, 0);
  g.addColorStop(0, base[0]); g.addColorStop(0.5, base[1]); g.addColorStop(1, base[0]);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.clip();
  // mottle: the cuticle is never one colour
  for (let i = 0; i < 260; i += 1) {
    const t = r(), side = r() * 2 - 1;
    const [x, y] = at(t, side);
    ctx.fillStyle = `rgba(${r() < 0.5 ? '255,255,230' : '20,30,10'},${0.04 + r() * 0.06})`;
    ctx.beginPath(); ctx.arc(x, y, 2 + r() * 7, 0, Math.PI * 2); ctx.fill();
  }
  // veins
  ctx.strokeStyle = vein;
  if (kind === 'strap') {
    ctx.lineWidth = 0.8;
    for (let k = -3; k <= 3; k += 1) {
      if (!k) continue;
      ctx.beginPath();
      for (let i = 0; i <= N; i += 2) {
        const t = i / N; const hw = pts[i][1];
        const x = cx + (k / 4) * hw, y = y0 + (y1 - y0) * t;
        i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      }
      ctx.stroke();
    }
  } else {
    const pairs = kind === 'cabbage' ? 7 : kind === 'bean' ? 6 : 8;
    ctx.lineWidth = kind === 'cabbage' ? 3.2 : 1.4;
    for (let k = 1; k <= pairs; k += 1) {
      const t = k / (pairs + 1.2);
      for (const side of [-1, 1]) {
        const [sx, sy] = [cx, y0 + (y1 - y0) * t];
        const [ex, ey] = at(Math.min(0.98, t + 0.16), side * 0.92);
        ctx.beginPath(); ctx.moveTo(sx, sy);
        ctx.quadraticCurveTo(cx + side * (ex - cx) * 0.4, (sy + ey) / 2 + 6, ex, ey);
        ctx.stroke();
      }
    }
  }
  // the midrib
  ctx.strokeStyle = rib;
  ctx.lineWidth = kind === 'cabbage' ? 9 : kind === 'strap' ? 3.5 : 4;
  ctx.beginPath(); ctx.moveTo(cx, y0 + 4); ctx.lineTo(cx, y1 + 10); ctx.stroke();
  ctx.restore();
}

/** A palmate, lobed leaf (cucurbit or berry) on a petiole from the tile's foot. */
function paintPalmate(ctx, ox, oy, kind, seed) {
  const r = rng(seed);
  const cx = ox + TILE / 2, cy = oy + TILE * (kind === 'berry' ? 0.56 : 0.54);
  const R = TILE * (kind === 'berry' ? 0.42 : 0.45);
  const lobes = kind === 'berry' ? 5 : 5;
  ctx.save();
  ctx.beginPath();
  const N = 180;
  for (let i = 0; i <= N; i += 1) {
    const a = (i / N) * Math.PI * 2 - Math.PI / 2;
    // the sinus at the petiole (bottom), lobes elsewhere
    const lobe = Math.abs(Math.cos((a + Math.PI / 2) * lobes / 2));
    let rr = R * (kind === 'berry' ? 0.62 + 0.38 * Math.pow(lobe, 0.7) : 0.8 + 0.2 * Math.pow(lobe, 1.5));
    const fromFoot = Math.abs(((a + Math.PI / 2 + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
    if (fromFoot < 0.35) rr *= 0.35 + fromFoot * 1.8;      // the cordate base
    // serration (berry) or a rough wavy margin (cucurbit)
    rr *= kind === 'berry' ? 1 - 0.05 * Math.abs(Math.sin(i * 1.9)) : 1 - 0.03 * Math.abs(Math.sin(i * 0.9 + r()));
    const x = cx + Math.cos(a) * rr * 0.98, y = cy - Math.sin(a) * rr;
    i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
  }
  ctx.closePath();
  const g = ctx.createRadialGradient(cx, cy, 4, cx, cy, R);
  if (kind === 'berry') { g.addColorStop(0, hsl(95, 38, 30)); g.addColorStop(1, hsl(88, 42, 38)); }
  else { g.addColorStop(0, hsl(92, 30, 33)); g.addColorStop(0.7, hsl(88, 34, 37)); g.addColorStop(1, hsl(80, 30, 41)); }
  ctx.fillStyle = g; ctx.fill();
  ctx.clip();
  for (let i = 0; i < 420; i += 1) {
    const a = r() * Math.PI * 2, d = Math.sqrt(r()) * R;
    ctx.fillStyle = `rgba(${r() < 0.55 ? '235,245,210' : '15,25,8'},${0.03 + r() * 0.06})`;
    ctx.beginPath(); ctx.arc(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 1.5 + r() * 5, 0, Math.PI * 2); ctx.fill();
  }
  // main veins out to the lobes, side veins off them
  ctx.strokeStyle = kind === 'berry' ? hsl(85, 30, 52, 0.7) : hsl(75, 28, 62, 0.75);
  for (let k = 0; k < lobes; k += 1) {
    const a = Math.PI / 2 + ((k - (lobes - 1) / 2) / ((lobes - 1) / 2)) * 2.3;
    ctx.lineWidth = 3;
    const ex = cx + Math.cos(a) * R * 0.92, ey = cy - Math.sin(a) * R * 0.92;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
    ctx.lineWidth = 1.1;
    for (let j = 1; j < 5; j += 1) {
      const f = j / 5, px = cx + (ex - cx) * f, py = cy + (ey - cy) * f;
      for (const s of [-1, 1]) {
        const b = a + s * 0.9;
        ctx.beginPath(); ctx.moveTo(px, py);
        ctx.lineTo(px + Math.cos(b) * R * 0.22 * (1 - f * 0.5), py - Math.sin(b) * R * 0.22 * (1 - f * 0.5));
        ctx.stroke();
      }
    }
  }
  ctx.restore();
  // the petiole down to the tile's foot
  ctx.strokeStyle = hsl(85, 30, 40);
  ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx, oy + TILE - 2); ctx.stroke();
}

/** A finely divided frond (carrot, parsnip, asparagus) up the tile. */
function paintFern(ctx, ox, oy, seed) {
  const r = rng(seed);
  const cx = ox + TILE / 2;
  ctx.save();
  ctx.lineCap = 'round';
  const stem = (x0, y0, ang, len, w, depth) => {
    const x1 = x0 + Math.cos(ang) * len, y1 = y0 - Math.sin(ang) * len;
    ctx.strokeStyle = hsl(95 + r() * 10, 40, 30 + r() * 10);
    ctx.lineWidth = w;
    ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
    if (depth <= 0) return;
    const n = depth === 2 ? 8 : 6;
    for (let i = 1; i <= n; i += 1) {
      const f = i / (n + 1);
      const px = x0 + (x1 - x0) * f, py = y0 + (y1 - y0) * f;
      for (const s of [-1, 1]) stem(px, py, ang + s * (0.75 + r() * 0.3), len * (0.42 - f * 0.22), Math.max(1, w * 0.55), depth - 1);
    }
  };
  stem(cx, oy + TILE - 2, Math.PI / 2, TILE * 0.94, 3.5, 2);
  ctx.restore();
}

/** A pinnate compound leaf (potato): leaflets in pairs up a rachis. */
function paintPinnate(ctx, ox, oy, seed) {
  const r = rng(seed);
  const cx = ox + TILE / 2;
  const y0 = oy + TILE - 4;
  ctx.save();
  ctx.strokeStyle = hsl(90, 30, 32); ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(cx, y0); ctx.lineTo(cx, oy + 30); ctx.stroke();
  const leaflet = (x, y, ang, len, wid) => {
    ctx.save(); ctx.translate(x, y); ctx.rotate(-ang);
    ctx.beginPath(); ctx.ellipse(len / 2, 0, len / 2, wid / 2, 0, 0, Math.PI * 2);
    const g = ctx.createLinearGradient(0, -wid / 2, 0, wid / 2);
    g.addColorStop(0, hsl(100, 32, 26)); g.addColorStop(0.5, hsl(96, 34, 33)); g.addColorStop(1, hsl(100, 32, 26));
    ctx.fillStyle = g; ctx.fill();
    ctx.strokeStyle = hsl(90, 25, 45, 0.6); ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(len * 0.95, 0); ctx.stroke();
    ctx.restore();
  };
  for (let i = 0; i < 4; i += 1) {
    const y = y0 - 50 - i * 46;
    const len = 62 - i * 6 + r() * 6;
    leaflet(cx, y, 0.35, len, len * 0.55);
    leaflet(cx, y, Math.PI - 0.35, len, len * 0.55);
    // the small interstitial leaflets
    leaflet(cx, y + 22, 0.6, 18, 10);
    leaflet(cx, y + 22, Math.PI - 0.6, 18, 10);
  }
  leaflet(cx, oy + 36, Math.PI / 2, 56, 34);
  ctx.restore();
}

const LEAF_CUTOFF = 0.45;
const makeCanvas = (w, h) => (typeof OffscreenCanvas !== 'undefined' ? new OffscreenCanvas(w, h)
  : Object.assign(document.createElement('canvas'), { width: w, height: h }));

/**
 * The atlas's mips, each tile holding the leaf area it had at full size. Averaged alpha
 * thins a cut leaf (a potato's leaflets, a corn blade) below the alpha test a few metres
 * off, and a bed seen from the fort read as bare earth; the trees' atlas does the same
 * (tree-surface.js foliageMipmaps).
 */
function coverageMips(source) {
  const W = source.width, H = source.height;
  const tiles = GRID[0] * GRID[1];
  const base = source.getContext('2d').getImageData(0, 0, W, H).data;
  const coverage = [];
  for (let t = 0; t < tiles; t += 1) {
    const bx = (t % GRID[0]) * TILE, by = Math.floor(t / GRID[0]) * TILE;
    let covered = 0;
    for (let y = 0; y < TILE; y += 1) for (let x = 0; x < TILE; x += 1) {
      if (base[((by + y) * W + bx + x) * 4 + 3] >= LEAF_CUTOFF * 255) covered += 1;
    }
    coverage.push(covered / (TILE * TILE));
  }
  const levels = [source];
  for (let k = 1; ; k += 1) {
    const w = Math.max(1, W >> k), h = Math.max(1, H >> k);
    const c = makeCanvas(w, h);
    const ctx = c.getContext('2d');
    ctx.drawImage(levels[k - 1], 0, 0, w, h);
    const ts = TILE >> k;
    if (ts >= 2) {
      const img = ctx.getImageData(0, 0, w, h);
      for (let t = 0; t < tiles; t += 1) {
        const bx = (t % GRID[0]) * ts, by = Math.floor(t / GRID[0]) * ts;
        const hist = new Uint32Array(256);
        for (let y = 0; y < ts; y += 1) for (let x = 0; x < ts; x += 1) hist[img.data[((by + y) * w + bx + x) * 4 + 3]] += 1;
        const target = coverage[t] * ts * ts;
        let sum = 0, threshold = 255;
        for (; threshold > 1 && sum < target; threshold -= 1) sum += hist[threshold];
        const gain = Math.max(1, (LEAF_CUTOFF * 255 + 2) / Math.max(1, threshold));
        for (let y = 0; y < ts; y += 1) for (let x = 0; x < ts; x += 1) {
          const at = ((by + y) * w + bx + x) * 4 + 3;
          img.data[at] = Math.min(255, img.data[at] * gain);
        }
      }
      ctx.putImageData(img, 0, 0);
    }
    levels.push(c);
    if (w === 1 && h === 1) break;
  }
  return levels;
}

const ATLAS = new Map();
/**
 * The leaf atlas, painted once per page; a canvas texture with mips. `lowSpec` (a phone)
 * gets it one level down, 512 x 256: a quarter of the bytes, and a leaf on a phone's
 * screen is never drawn larger than that level holds (T-3407 follow-up, 1812 phone
 * memory over its ceiling).
 */
export function cropAtlas(lowSpec = false) {
  if (ATLAS.has(lowSpec)) return ATLAS.get(lowSpec);
  const canvas = typeof OffscreenCanvas !== 'undefined'
    ? new OffscreenCanvas(TILE * GRID[0], TILE * GRID[1])
    : Object.assign(document.createElement('canvas'), { width: TILE * GRID[0], height: TILE * GRID[1] });
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const o = (tile) => [(tile % GRID[0]) * TILE, Math.floor(tile / GRID[0]) * TILE];
  paintBlade(ctx, ...o(LEAF.strap), 'strap', [hsl(92, 34, 30), hsl(88, 38, 38)], hsl(70, 30, 70, 0.85), hsl(90, 30, 46, 0.35), 11);
  paintPalmate(ctx, ...o(LEAF.cucurbit), 'cucurbit', 12);
  paintBlade(ctx, ...o(LEAF.bean), 'bean', [hsl(98, 36, 27), hsl(94, 40, 34)], hsl(88, 30, 48, 0.8), hsl(90, 30, 44, 0.5), 13);
  paintBlade(ctx, ...o(LEAF.cabbage), 'cabbage', [hsl(150, 18, 44), hsl(140, 20, 54)], hsl(110, 20, 82, 0.95), hsl(120, 18, 76, 0.65), 14);
  paintBlade(ctx, ...o(LEAF.beet), 'beet', [hsl(110, 40, 20), hsl(100, 38, 27)], hsl(350, 70, 38), hsl(350, 55, 34, 0.75), 15);
  paintFern(ctx, ...o(LEAF.fern), 16);
  paintPinnate(ctx, ...o(LEAF.potato), 17);
  paintPalmate(ctx, ...o(LEAF.berry), 'berry', 18);
  const mips = coverageMips(canvas);
  const levels = lowSpec ? mips.slice(1) : mips;
  const tex = new THREE.CanvasTexture(levels[0]);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.mipmaps = levels;
  tex.generateMipmaps = false;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.anisotropy = 4;
  tex.name = 'garden-crop-atlas';
  ATLAS.set(lowSpec, tex);
  return tex;
}

/** A tile's (u, v) to atlas UV, with a small inset so mips do not bleed. */
function atlasUV(tile, u, v) {
  const pad = 3 / TILE;
  const cx = tile % GRID[0], cy = Math.floor(tile / GRID[0]);
  return [(cx + pad + u * (1 - 2 * pad)) / GRID[0], 1 - (cy + pad + (1 - v) * (1 - 2 * pad)) / GRID[1]];
}

/* -------------------------------------------------------------------------- */
/* soil textures                                                               */
/* -------------------------------------------------------------------------- */

function soilCanvas(kind, seed, lowSpec = false) {
  const S = 256;
  const canvas = typeof OffscreenCanvas !== 'undefined' ? new OffscreenCanvas(S, S)
    : Object.assign(document.createElement('canvas'), { width: S, height: S });
  const ctx = canvas.getContext('2d');
  const r = rng(seed);
  const base = kind === 'bed' ? [74, 58, 42] : [122, 104, 80];
  ctx.fillStyle = `rgb(${base.join(',')})`;
  ctx.fillRect(0, 0, S, S);
  // wrapping so the tile repeats without a seam
  const dab = (x, y, rad, style) => {
    ctx.fillStyle = style;
    for (const dx of [-S, 0, S]) for (const dy of [-S, 0, S]) {
      ctx.beginPath(); ctx.arc(x + dx, y + dy, rad, 0, Math.PI * 2); ctx.fill();
    }
  };
  // broad, soft patches first: damp and dry, so the ground is never one flat colour
  for (let i = 0; i < 70; i += 1) {
    const k = r() < 0.5 ? 0.78 : 1.16;
    dab(r() * S, r() * S, 14 + r() * 40, `rgba(${base.map((v) => Math.round(v * k)).join(',')},${0.08 + r() * 0.1})`);
  }
  // then crumbs: many and small, darker in their shadow than lit on top
  const n = kind === 'bed' ? 5200 : 3600;
  for (let i = 0; i < n; i += 1) {
    const x = r() * S, y = r() * S, rad = kind === 'bed' ? 0.35 + r() * r() * 2.2 : 0.3 + r() * r() * 1.4;
    const lit = r() < 0.5;
    const k = lit ? 1.08 + r() * 0.22 : 0.6 + r() * 0.22;
    dab(x, y, rad, `rgba(${base.map((v) => Math.round(v * k)).join(',')},${0.3 + r() * 0.4})`);
  }
  // a few small stones, each with its shadow under it
  for (let i = 0; i < (kind === 'bed' ? 40 : 90); i += 1) {
    const x = r() * S, y = r() * S, rad = 0.6 + r() * 1.3, g = 120 + r() * 50;
    dab(x + 0.5, y + 0.7, rad, 'rgba(30,24,18,0.35)');
    dab(x, y, rad, `rgba(${Math.round(g)},${Math.round(g * 0.93)},${Math.round(g * 0.82)},0.8)`);
  }
  if (kind === 'walk') {
    // trodden: a few blades of grass surviving and the odd pebble
    for (let i = 0; i < 160; i += 1) {
      const x = r() * S, y = r() * S;
      ctx.strokeStyle = `rgba(${80 + r() * 40},${100 + r() * 40},${50 + r() * 20},${0.5 + r() * 0.4})`;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (r() - 0.5) * 5, y - 3 - r() * 6); ctx.stroke();
    }
  } else {
    // a hoe's strokes across the bed
    for (let i = 0; i < 60; i += 1) {
      const y = r() * S, x = r() * S;
      ctx.strokeStyle = `rgba(40,30,20,${0.15 + r() * 0.15})`;
      ctx.lineWidth = 1.5 + r() * 2;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 18 + r() * 30, y + (r() - 0.5) * 4); ctx.stroke();
    }
  }
  let image = canvas;
  if (lowSpec) {
    // a phone keeps the 128 px level: a quarter of the bytes, the same ground at its distance
    image = typeof OffscreenCanvas !== 'undefined' ? new OffscreenCanvas(S / 2, S / 2)
      : Object.assign(document.createElement('canvas'), { width: S / 2, height: S / 2 });
    image.getContext('2d').drawImage(canvas, 0, 0, S / 2, S / 2);
  }
  const tex = new THREE.CanvasTexture(image);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.anisotropy = 4;
  tex.name = `garden-soil-${kind}`;
  return tex;
}

/* -------------------------------------------------------------------------- */
/* a geometry buffer                                                           */
/* -------------------------------------------------------------------------- */

class Buf {
  constructor() { this.pos = []; this.nrm = []; this.uv = []; this.col = []; this.idx = []; }
  get count() { return this.pos.length / 3; }
  v(p, n, uv, c) {
    this.pos.push(p[0], p[1], p[2]);
    const l = Math.hypot(n[0], n[1], n[2]) || 1;
    this.nrm.push(n[0] / l, n[1] / l, n[2] / l);
    this.uv.push(uv[0], uv[1]);
    this.col.push(c[0], c[1], c[2]);
    return this.count - 1;
  }
  t(a, b, c) { this.idx.push(a, b, c); }
  geometry(conf) {
    const g = new THREE.BufferGeometry();
    const n = this.count;
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    // the colours above are written as a painter sees them (sRGB); three lights in linear
    const lin = this.col.map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    g.setAttribute('color', new THREE.Float32BufferAttribute(lin, 3));
    g.setAttribute('_confidence', new THREE.BufferAttribute(new Float32Array(n).fill(conf), 1));
    g.setIndex(n > 65535 ? new THREE.Uint32BufferAttribute(this.idx, 1) : new THREE.Uint16BufferAttribute(this.idx, 1));
    g.computeBoundingBox();
    g.computeBoundingSphere();
    return g;
  }
}

const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const mul = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a) => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const tint = (c, k) => [c[0] * k, c[1] * k, c[2] * k];

/**
 * One leaf card, bent: from `base` it heads along `dir` (a unit vector), rising by `rise`
 * and drooping by `droop` (fractions of its length) so the tip arches, `wid` wide across
 * `side`, folded along its midrib by `fold` (0 flat, 1 a deep V). `segs` rows of three
 * vertices; the card's normals lean out from the plant's middle (`centre`) so a clump
 * lights as one mass, the way a real leaf mass does.
 */
function leafCard(b, { base, dir, side, len, wid, tile, rise = 0.2, droop = 0.4, fold = 0.25, segs = 3,
  col = [1, 1, 1], centre = null, twist = 0 }) {
  const up = [0, 1, 0];
  let s = norm(side);
  const rows = [];
  for (let i = 0; i <= segs; i += 1) {
    const t = i / segs;
    // the spine: along dir, up by rise*t, down by droop*t^2
    const p = add(base, add(mul(dir, len * t), mul(up, len * (rise * t - droop * t * t))));
    const tw = twist * t;
    const sTw = norm(add(mul(s, Math.cos(tw)), mul(up, Math.sin(tw))));
    rows.push({ p, s: sTw, t });
  }
  const ids = [];
  for (const { p, s: sv, t } of rows) {
    const tangent = norm(sub(rows[Math.min(segs, Math.round(t * segs) + 1)].p, rows[Math.max(0, Math.round(t * segs) - 1)].p));
    let n = norm(cross(sv, tangent));
    if (n[1] < 0) n = mul(n, -1);
    if (centre) n = norm(add(mul(n, 0.55), mul(norm(sub(p, centre)), 0.45)));
    const half = wid / 2;
    const lift = mul(n, fold * half * 0.6);
    const shade = 0.78 + 0.22 * t;     // a leaf's foot sits in the plant's shade
    const c = tint(col, shade);
    const l = b.v(add(add(p, mul(sv, -half)), [0, 0, 0]), n, atlasUV(tile, 0, t), c);
    const m = b.v(add(p, mul(lift, -1)), n, atlasUV(tile, 0.5, t), tint(c, 0.92));
    const r = b.v(add(p, mul(sv, half)), n, atlasUV(tile, 1, t), c);
    ids.push([l, m, r]);
  }
  for (let i = 0; i < segs; i += 1) {
    const [a0, a1, a2] = ids[i], [b0, b1, b2] = ids[i + 1];
    b.t(a0, a1, b1); b.t(a0, b1, b0); b.t(a1, a2, b2); b.t(a1, b2, b1);
  }
}

/** A flat card standing on its own (a palmate leaf on its petiole, a fern frond):
 *  the tile's foot at `base`, its face turned `facing`, tipped up by `tilt` radians. */
function blade(b, { base, heading, tilt, len, wid, tile, col, centre, cup = 0.15, segs = 2 }) {
  const dir = [Math.cos(heading) * Math.cos(tilt), Math.sin(tilt), Math.sin(heading) * Math.cos(tilt)];
  const side = [-Math.sin(heading), 0, Math.cos(heading)];
  leafCard(b, { base, dir, side, len, wid, tile, rise: 0, droop: 0.12, fold: cup, segs, col, centre });
}

/** A tapered tube from a to b (stalk, stem, vine, pole), `k` sides. */
function tube(b, a, z, r0, r1, col, k = 5, colTop = null) {
  const axis = norm(sub(z, a));
  const ref = Math.abs(axis[1]) > 0.9 ? [1, 0, 0] : [0, 1, 0];
  const u = norm(cross(axis, ref)), w = cross(axis, u);
  const base = b.count;
  for (let i = 0; i <= 1; i += 1) {
    const c = i ? z : a, r = i ? r1 : r0;
    for (let j = 0; j < k; j += 1) {
      const ang = (j / k) * Math.PI * 2;
      const n = add(mul(u, Math.cos(ang)), mul(w, Math.sin(ang)));
      b.v(add(c, mul(n, r)), n, [0, 0], i && colTop ? colTop : col);
    }
  }
  for (let j = 0; j < k; j += 1) {
    const j1 = (j + 1) % k;
    b.t(base + j, base + j1, base + k + j1);
    b.t(base + j, base + k + j1, base + k + j);
  }
}

/** A polyline tube through points (a vine, a cane): one ring per point. */
function polyTube(b, pts, r0, r1, col, k = 4) {
  for (let i = 1; i < pts.length; i += 1) {
    const f0 = (i - 1) / (pts.length - 1), f1 = i / (pts.length - 1);
    tube(b, pts[i - 1], pts[i], r0 + (r1 - r0) * f0, r0 + (r1 - r0) * f1, col, k);
  }
}

/** An ellipsoid (a melon, a cabbage's head, a hill of earth), with a colour function
 *  over its surface (lat -1..1, lon 0..1) so a rind can be striped or netted. */
function ellipsoid(b, c, rx, ry, rz, colorAt, { lat = 6, lon = 10, yaw = 0, cutBelow = -1 } = {}) {
  const cy = Math.cos(yaw), sy = Math.sin(yaw);
  const rows = [];
  for (let i = 0; i <= lat; i += 1) {
    const phi = -Math.PI / 2 + (i / lat) * Math.PI;
    const ring = [];
    const sinP = Math.max(cutBelow, Math.sin(phi));
    const cosP = Math.sqrt(Math.max(0, 1 - sinP * sinP));
    for (let j = 0; j <= lon; j += 1) {
      const th = (j / lon) * Math.PI * 2;
      const lx = cosP * Math.cos(th) * rx, lz = cosP * Math.sin(th) * rz, ly = sinP * ry;
      const p = [c[0] + lx * cy - lz * sy, c[1] + ly, c[2] + lx * sy + lz * cy];
      const nl = [lx / (rx * rx), ly / (ry * ry), lz / (rz * rz)];
      const n = [nl[0] * cy - nl[2] * sy, nl[1], nl[0] * sy + nl[2] * cy];
      ring.push(b.v(p, n, [0, 0], colorAt(sinP, j / lon)));
    }
    rows.push(ring);
  }
  for (let i = 0; i < lat; i += 1) {
    for (let j = 0; j < lon; j += 1) {
      const a = rows[i][j], bb = rows[i][j + 1], c2 = rows[i + 1][j + 1], d = rows[i + 1][j];
      b.t(a, c2, bb); b.t(a, d, c2);
    }
  }
}

/* -------------------------------------------------------------------------- */
/* the crops                                                                   */
/* -------------------------------------------------------------------------- */

/** Colours in linear-ish 0..1, the vertex tints over the atlas's painted leaf. */
const GREEN = [1, 1, 1];
const SOIL = [0.24, 0.18, 0.12];
const STALK = [0.32, 0.42, 0.17];
const STRAW = [0.62, 0.52, 0.32];
const POLE = [0.38, 0.33, 0.27];

function hills(sb, r, w, h, lod = 'near') {
  // a low hill of drawn-up earth
  ellipsoid(sb, [0, 0, 0], w, h, w * (0.85 + r() * 0.2), () => tint(SOIL, 0.9 + r() * 0.2), { lat: q(lod, 3, 2, 1), lon: q(lod, 8, 6, 5), cutBelow: 0 });
}

/**
 * A count, a ring count or a subdivision at each level: `a` near, `b` mid, and at `far`
 * about half of mid, never under `lo`. `whole` false keeps a fraction (a share of a row).
 */
function q(lod, a, b, lo = 1, whole = true) {
  if (lod === 'near') return a;
  if (lod === 'mid') return b;
  const v = b * 0.5;
  return Math.max(lo, whole ? Math.round(v) : v);
}

/**
 * Each builder grows ONE plant at the origin (+y up, the plant's own +x along its row)
 * into a leaf buffer `lb` (atlas cards) and a solid buffer `sb` (stalks, poles, fruit,
 * earth), at `lod` 'near' or 'far'. `r` is the variant's own random stream.
 */
export const CROPS = {
  /** Indian corn, two stalks to a hill (M'Mahon: "two grains in each place"), tasselled,
   *  an ear silking on most. */
  corn(lb, sb, r, lod) {
    const near = lod === 'near';
    hills(sb, r, 0.3, 0.09, lod);
    const stalks = 2;
    for (let k = 0; k < stalks; k += 1) {
      const a = (k / stalks) * Math.PI * 2 + r();
      const foot = [Math.cos(a) * 0.1, 0.05, Math.sin(a) * 0.1];
      const h = 1.9 + r() * 0.6;
      const lean = [(r() - 0.5) * 0.18, 0, (r() - 0.5) * 0.18];
      const top = add(foot, add([0, h, 0], lean));
      tube(sb, foot, top, 0.022, 0.011, STALK, q(lod, 5, 3, 3));
      const leaves = q(lod, 11, 6);
      for (let i = 0; i < leaves; i += 1) {
        const f = 0.08 + (i / leaves) * 0.8;
        const p = add(foot, mul(sub(top, foot), f));
        const head = (i * Math.PI) + (r() - 0.5) * 0.8 + a;      // two-ranked, alternate
        const dir = norm([Math.cos(head), 0.55 - f * 0.25, Math.sin(head)]);
        const side = [-Math.sin(head), 0, Math.cos(head)];
        leafCard(lb, { base: p, dir, side, len: 0.62 + (1 - Math.abs(f - 0.45)) * 0.35, wid: 0.3,
          tile: LEAF.strap, rise: 0.15, droop: 0.75 + r() * 0.3, fold: 0.35, segs: q(lod, 4, 2, 1),
          col: tint(GREEN, f < 0.2 ? 0.8 + r() * 0.1 : 0.95 + r() * 0.1), twist: (r() - 0.5) * 0.8 });
      }
      // the tassel: a spray of thin spikes
      const spikes = q(lod, 7, 3);
      for (let i = 0; i < spikes; i += 1) {
        const ang = (i / spikes) * Math.PI * 2 + r();
        const tip = add(top, [Math.cos(ang) * 0.12, 0.2 + r() * 0.08, Math.sin(ang) * 0.12]);
        tube(sb, top, tip, 0.005, 0.002, STRAW, 3);
      }
      tube(sb, top, add(top, [0, 0.32, 0]), 0.006, 0.003, STRAW, 3);
      // the ear: a green husk, its silk browning in mid-August
      if (r() < 0.85) {
        const ef = 0.42 + r() * 0.12;
        const ep = add(foot, mul(sub(top, foot), ef));
        const ea = a + Math.PI * 0.5 + (r() - 0.5);
        const out = [Math.cos(ea) * 0.07, 0.17, Math.sin(ea) * 0.07];
        tube(sb, ep, add(ep, out), 0.028, 0.02, [0.42, 0.5, 0.24], q(lod, 6, 4, 3));
        tube(sb, add(ep, out), add(ep, mul(out, 1.35)), 0.012, 0.004, [0.45, 0.3, 0.16], 3);
      }
    }
  },

  /** A pole bean: the pole driven in its hill and the vine wound up it, in leaf and pod. */
  pole_bean(lb, sb, r, lod) {
    const near = lod === 'near';
    hills(sb, r, 0.26, 0.07, lod);
    const h = 2.4 + r() * 0.4;
    const top = [(r() - 0.5) * 0.12, h, (r() - 0.5) * 0.12];
    tube(sb, [0, -0.1, 0], top, 0.028, 0.02, tint(POLE, 0.85 + r() * 0.3), q(lod, 5, 4, 3));
    // M'Mahon sets several beans to a pole; two vines wind up it, against the sun, and by
    // mid-August they have clothed it from the hill to the top in leaf
    const grow = lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.45;   // fewer, larger cards farther off
    const nodes = q(lod, 20, 9);
    for (const twin of [0, Math.PI]) {
      const turns = 3 + r() * 0.6;
      const pts = [];
      const steps = q(lod, 24, 10);
      for (let i = 0; i <= steps; i += 1) {
        const t = i / steps;
        const ang = twin + t * turns * Math.PI * 2;
        const c = mul(top, t * 0.96);
        pts.push(add(c, [Math.cos(ang) * 0.035, 0.05, Math.sin(ang) * 0.035]));
      }
      if (lod !== 'far') polyTube(sb, pts, 0.006, 0.004, [0.3, 0.42, 0.16], 3);
      for (let i = 1; i < nodes; i += 1) {
        const t = (i + (twin ? 0.5 : 0)) / nodes;
        const c = mul(top, t * 0.95);
        const head = r() * Math.PI * 2;
        // a trifoliate leaf: three leaflets on a short stalk, the upper ones younger
        const reach = 0.07 + r() * 0.12 * (1.1 - t * 0.4);
        const size = (1.05 - t * 0.3) * grow;
        const stalkEnd = add(c, [Math.cos(head) * reach, 0.03, Math.sin(head) * reach]);
        for (let k = -1; k <= 1; k += 1) {
          const hd = head + k * 0.9;
          const dir = norm([Math.cos(hd), k ? -0.2 : 0.15, Math.sin(hd)]);
          leafCard(lb, { base: stalkEnd, dir, side: [-Math.sin(hd), 0, Math.cos(hd)], len: (0.12 + r() * 0.05) * size,
            wid: 0.11 * size, tile: LEAF.bean, rise: 0, droop: 0.35, fold: 0.15, segs: q(lod, 2, 1, 1),
            col: tint(GREEN, 0.86 + r() * 0.22), centre: mul(top, 0.5) });
        }
        // pods hang under the leaves on the lower two-thirds
        if (near && t < 0.7 && r() < 0.45) {
          const p0 = add(c, [Math.cos(head + 1.6) * 0.05, -0.02, Math.sin(head + 1.6) * 0.05]);
          tube(sb, p0, add(p0, [(r() - 0.5) * 0.04, -0.14 - r() * 0.05, (r() - 0.5) * 0.04]), 0.006, 0.004, [0.38, 0.5, 0.2], 3);
        }
      }
    }
  },

  /** A cabbage or savoy: the outer leaves spread, a firm head in the middle. */
  cabbage(lb, sb, r, lod) {
    const near = lod === 'near';
    const savoy = r() < 0.35;
    const head = 0.13 + r() * 0.05;
    const hc = [0, head * 0.85, 0];
    const headCol = savoy ? [0.36, 0.48, 0.3] : [0.55, 0.66, 0.52];
    ellipsoid(sb, hc, head, head * 0.88, head, (y) => tint(headCol, 0.85 + y * 0.15), { lat: q(lod, 6, 4, 2), lon: q(lod, 10, 6, 5) });
    const leaves = q(lod, 10, 6);
    for (let i = 0; i < leaves; i += 1) {
      const a = (i / leaves) * Math.PI * 2 + r() * 0.4;
      const tilt = 0.25 + r() * 0.5;
      blade(lb, { base: [Math.cos(a) * 0.04, 0.06, Math.sin(a) * 0.04], heading: a, tilt, len: 0.32 + r() * 0.1,
        wid: 0.3 + r() * 0.06, tile: LEAF.cabbage, col: tint(GREEN, savoy ? 0.8 : 0.95 + r() * 0.1),
        centre: [0, 0.4, 0], cup: 0.5 });
    }
    // the wrapper leaves clasping the head
    if (near) {
      for (let i = 0; i < 4; i += 1) {
        const a = (i / 4) * Math.PI * 2 + r();
        blade(lb, { base: [Math.cos(a) * 0.03, 0.04, Math.sin(a) * 0.03], heading: a, tilt: 1.15, len: head * 1.9,
          wid: head * 2.1, tile: LEAF.cabbage, col: tint(GREEN, 1.05), centre: hc, cup: 0.9 });
      }
    }
  },

  /** A potato hill: the earth drawn up round it, a bushy top beginning to yellow. */
  potato(lb, sb, r, lod) {
    const near = lod === 'near';
    hills(sb, r, 0.38, 0.16, lod);
    const stems = q(lod, 7, 5);
    const grow = lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.5;
    for (let s = 0; s < stems; s += 1) {
      const a = (s / stems) * Math.PI * 2 + r();
      const lean = 0.5 + r() * 0.5;
      const tip = [Math.cos(a) * lean * 0.5, 0.5 + r() * 0.25, Math.sin(a) * lean * 0.5];
      tube(sb, [0, 0.1, 0], tip, 0.012, 0.007, [0.3, 0.38, 0.16], 3);
      const n = q(lod, 6, 4);
      for (let i = 0; i < n; i += 1) {
        const f = 0.3 + (i / n) * 0.7;
        const p = mul(tip, f);
        p[1] += 0.1 * (1 - f);
        const hd = a + (i % 2 ? 1 : -1) * (0.9 + r() * 0.5);
        const yellow = r() < 0.18 ? [1.25, 1.12, 0.55] : [1, 1, 1];
        blade(lb, { base: p, heading: hd, tilt: 0.1 + r() * 0.35, len: (0.26 + r() * 0.08) * grow, wid: 0.2 * grow,
          tile: LEAF.potato, col: mul(yellow, 0.95 + r() * 0.2), centre: [0, 0.3, 0], cup: 0.1, segs: q(lod, 2, 1, 1) });
      }
    }
    // the odd white flower left late
    if (near && r() < 0.4) ellipsoid(sb, [0.05, 0.62, 0.02], 0.025, 0.012, 0.025, () => [0.9, 0.88, 0.82], { lat: 2, lon: 5 });
  },

  /** Melon or cucumber hill: vines running out over the bed, leaves held up off it, and
   *  the fruit lying in the leaves. `fruit` picks the rind. */
  vine(lb, sb, r, lod, fruit) {
    const near = lod === 'near';
    hills(sb, r, 0.35, 0.08, lod);
    const runners = q(lod, 5, 3);
    // mid-August: the runners have met across the hills and the bed is a mat of leaf
    const spread = { squash: 1.6, watermelon: 2.1, muskmelon: 1.5, cucumber: 1.2 }[fruit] ?? 1.2;
    const bigLeaf = fruit === 'squash' ? 0.3 : fruit === 'watermelon' ? 0.15 : 0.17;
    for (let k = 0; k < runners; k += 1) {
      const a = (k / runners) * Math.PI * 2 + r() * 0.8;
      const L = spread * (0.65 + r() * 0.45);
      const pts = [];
      const steps = q(lod, 6, 3);
      for (let i = 0; i <= steps; i += 1) {
        const t = i / steps;
        const wob = Math.sin(t * 5 + k) * 0.12 * t;
        pts.push([Math.cos(a + wob) * L * t, 0.04 + 0.02 * Math.sin(t * 9), Math.sin(a + wob) * L * t]);
      }
      polyTube(sb, pts, 0.01, 0.006, [0.33, 0.44, 0.18], 3);
      const leaves = q(lod, 9, 4);
      for (let i = 0; i < leaves; i += 1) {
        const t = 0.12 + (i / leaves) * 0.9;
        const p = pts[Math.min(steps, Math.round(t * steps))];
        const hd = a + (i % 2 ? 1.4 : -1.4) + (r() - 0.5) * 0.6;
        const stalk = 0.08 + r() * (fruit === 'squash' ? 0.25 : 0.1);
        const s = add(p, [Math.cos(hd) * 0.04, stalk, Math.sin(hd) * 0.04]);
        if (near) tube(sb, p, s, 0.005, 0.004, [0.36, 0.46, 0.2], 3);
        const sz = bigLeaf * (0.75 + r() * 0.5) * (lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.45);
        blade(lb, { base: s, heading: hd, tilt: 0.35 + r() * 0.5, len: sz * 1.9, wid: sz * 2,
          tile: LEAF.cucurbit, col: tint(GREEN, (fruit === 'watermelon' ? 0.85 : 0.95) + r() * 0.12),
          centre: [0, -0.2, 0], cup: 0.3 });
      }
      // fruit on the runner
      const fruits = fruit === 'cucumber' ? 2 : 1;
      for (let f = 0; f < fruits; f += 1) {
        if (r() < 0.25) continue;
        const t = 0.45 + r() * 0.45;
        const p = pts[Math.min(steps, Math.round(t * steps))];
        const yaw = a + (r() - 0.5);
        if (fruit === 'muskmelon') {
          const R = 0.09 + r() * 0.04; const ripe = r();
          const base = ripe < 0.5 ? [0.55, 0.55, 0.32] : [0.66, 0.58, 0.36];
          ellipsoid(sb, [p[0], R * 0.8, p[2]], R * 1.08, R * 0.92, R, (y, u) => {
            const net = (Math.sin(u * 80 + y * 23) * Math.sin(y * 31 - u * 37) > 0.55) ? 1.25 : 1;
            const rib = 0.92 + 0.08 * Math.cos(u * Math.PI * 20);
            return tint(base, net * rib);
          }, { lat: q(lod, 6, 4, 2), lon: q(lod, 12, 8, 5), yaw });
        } else if (fruit === 'watermelon') {
          const R = 0.12 + r() * 0.06;
          ellipsoid(sb, [p[0], R * 0.75, p[2]], R * 1.55, R * 0.88, R, (y, u) => {
            const stripe = Math.cos(u * Math.PI * 2 * 9 + Math.sin(y * 6) * 0.9) > 0.15;
            const c = stripe ? [0.11, 0.24, 0.09] : [0.32, 0.46, 0.22];
            return y < -0.55 ? [0.62, 0.6, 0.36] : c;           // the ground spot
          }, { lat: q(lod, 6, 4, 2), lon: q(lod, 14, 8, 5), yaw });
        } else if (fruit === 'squash') {
          const R = 0.13 + r() * 0.08; const turned = r();
          const c = turned < 0.4 ? [0.3, 0.42, 0.18] : turned < 0.75 ? [0.62, 0.45, 0.12] : [0.78, 0.4, 0.07];
          ellipsoid(sb, [p[0], R * 0.72, p[2]], R * 1.12, R * 0.8, R * 1.12, (y, u) => {
            const rib = 0.82 + 0.18 * Math.abs(Math.cos(u * Math.PI * 10));
            return tint(c, rib * (0.9 + y * 0.1));
          }, { lat: q(lod, 5, 4, 2), lon: q(lod, 16, 10, 5), yaw });
          tube(sb, [p[0], R * 1.45, p[2]], [p[0] + 0.02, R * 1.65, p[2]], 0.012, 0.009, [0.4, 0.36, 0.2], 4);
        } else {
          const R = 0.028; const L = 0.1 + r() * 0.04;
          ellipsoid(sb, [p[0], R + 0.01, p[2]], L, R, R, (y, u) => tint([0.2, 0.34, 0.12], 0.9 + 0.2 * (Math.sin(u * 60) > 0.6)), { lat: q(lod, 4, 3, 2), lon: q(lod, 8, 6, 5), yaw });
        }
      }
    }
  },

  /** A short length of a drilled row of roots or salad: `kind` beet, carrot, parsnip,
   *  onion, lettuce. One instance is ROW_M of row. */
  row(lb, sb, r, lod, kind) {
    const near = lod === 'near';
    const L = 1.0;
    const n = { beet: 7, carrot: 10, parsnip: 6, onion: 9, lettuce: 4 }[kind] * q(lod, 1, 0.5, 0.3, false);
    // the drill's ridge
    if (lod !== 'far') ellipsoid(sb, [0, 0, 0], L / 2, 0.035, 0.09, () => tint(SOIL, 0.95 + r() * 0.1), { lat: 2, lon: 8, cutBelow: 0 });
    for (let i = 0; i < n; i += 1) {
      const x = -L / 2 + (i + 0.5 + (r() - 0.5) * 0.5) * (L / n);
      const z = (r() - 0.5) * 0.06;
      const base = [x, 0.02, z];
      if (kind === 'onion') {
        // blue-green hollow leaves, half of them fallen over: the August sign they are ripe
        if (lod !== 'far') ellipsoid(sb, [x, 0.03, z], 0.035, 0.03, 0.035, () => [0.62, 0.48, 0.3], { lat: 3, lon: 6 });
        const fallen = r() < 0.55;
        const leaves = q(lod, 4, 2);
        for (let k = 0; k < leaves; k += 1) {
          const a = r() * Math.PI * 2;
          const dir = fallen ? norm([Math.cos(a), 0.2, Math.sin(a)]) : norm([Math.cos(a) * 0.25, 1, Math.sin(a) * 0.25]);
          leafCard(lb, { base: [x, 0.05, z], dir, side: [-Math.sin(a), 0, Math.cos(a)], len: 0.32 + r() * 0.12,
            wid: 0.022, tile: LEAF.strap, rise: 0, droop: fallen ? 0.25 : 0.4, fold: 0.6, segs: q(lod, 3, 1, 1),
            col: fallen && r() < 0.5 ? [1.35, 1.15, 0.55] : [0.82, 1.0, 1.12] });
        }
      } else if (kind === 'carrot' || kind === 'parsnip') {
        const fronds = q(lod, 5, 3);
        for (let k = 0; k < fronds; k += 1) {
          const a = r() * Math.PI * 2;
          blade(lb, { base, heading: a, tilt: 0.9 + r() * 0.5, len: (kind === 'parsnip' ? 0.42 : 0.32) + r() * 0.1,
            wid: 0.16, tile: kind === 'parsnip' ? LEAF.bean : LEAF.fern, col: tint(GREEN, 0.9 + r() * 0.2), cup: 0, segs: q(lod, 2, 1, 1) });
        }
        if (near) ellipsoid(sb, [x, 0.02, z], 0.018, 0.01, 0.018, () => [0.75, 0.42, 0.12], { lat: 2, lon: 5 });
      } else if (kind === 'beet') {
        if (lod !== 'far') ellipsoid(sb, [x, 0.035, z], 0.04, 0.035, 0.04, () => [0.36, 0.08, 0.12], { lat: 3, lon: 6 });
        const leaves = q(lod, 6, 3);
        for (let k = 0; k < leaves; k += 1) {
          const a = r() * Math.PI * 2;
          const tilt = 0.8 + r() * 0.5;
          blade(lb, { base: [x, 0.05, z], heading: a, tilt, len: 0.24 + r() * 0.08, wid: 0.11,
            tile: LEAF.beet, col: tint(GREEN, 0.9 + r() * 0.2), cup: 0.2, segs: q(lod, 3, 1, 1) });
        }
      } else {
        // lettuce gone to a loose head; endive's ragged rosette
        const leaves = q(lod, 8, 4);
        for (let k = 0; k < leaves; k += 1) {
          const a = (k / leaves) * Math.PI * 2 + r();
          blade(lb, { base: [x, 0.02, z], heading: a, tilt: 0.3 + (k % 2) * 0.6, len: 0.15 + r() * 0.05,
            wid: 0.15, tile: LEAF.cabbage, col: [1.05, 1.25, 0.8], centre: [x, 0.15, z], cup: 0.6, segs: q(lod, 2, 1, 1) });
        }
      }
    }
  },

  /** A currant or gooseberry bush: a stool of stems, the fruit mostly picked. */
  berry_bush(lb, sb, r, lod, kind) {
    const near = lod === 'near';
    const h = (kind === 'gooseberry' ? 0.9 : 1.15) + r() * 0.3;
    const grow = lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.5;
    const stems = q(lod, 9, 5);
    for (let s = 0; s < stems; s += 1) {
      const a = (s / stems) * Math.PI * 2 + r() * 0.5;
      const out = 0.25 + r() * 0.35;
      const mid = [Math.cos(a) * out * 0.5, h * 0.55, Math.sin(a) * out * 0.5];
      const tip = [Math.cos(a) * out, h * (0.85 + r() * 0.2), Math.sin(a) * out];
      polyTube(sb, [[0, 0, 0], mid, tip], 0.014, 0.005, [0.34, 0.27, 0.2], 3);
      const leaves = q(lod, 14, 7);
      for (let i = 0; i < leaves; i += 1) {
        const f = 0.2 + (i / leaves) * 0.8;
        const p = f < 0.55 ? mul(mid, f / 0.55) : add(mid, mul(sub(tip, mid), (f - 0.55) / 0.45));
        const hd = a + (r() - 0.5) * 2.4;
        blade(lb, { base: p, heading: hd, tilt: 0.2 + r() * 0.6, len: (0.13 + r() * 0.05) * grow, wid: 0.14 * grow,
          tile: LEAF.berry, col: tint(GREEN, 0.85 + r() * 0.25), centre: [0, h * 0.55, 0], cup: 0.2, segs: 1 });
      }
      // a few strings of late fruit left on the bush
      if (near && r() < 0.35) {
        const p = mul(mid, 1.1);
        const red = kind === 'gooseberry' ? [0.5, 0.55, 0.25] : [0.55, 0.06, 0.06];
        for (let k = 0; k < 4; k += 1) ellipsoid(sb, add(p, [0, -0.02 - k * 0.018, 0.01 * k]), 0.008, 0.008, 0.008, () => red, { lat: 2, lon: 4 });
      }
    }
  },

  /** Raspberry canes: this year's arching green canes and last year's brown, spent. */
  raspberry(lb, sb, r, lod) {
    const near = lod === 'near';
    const canes = q(lod, 7, 4);
    const grow = lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.5;
    for (let c = 0; c < canes; c += 1) {
      const a = r() * Math.PI * 2;
      const old = r() < 0.3;
      const h = 1.3 + r() * 0.5;
      const reach = 0.35 + r() * 0.3;
      const pts = [];
      for (let i = 0; i <= 4; i += 1) {
        const t = i / 4;
        pts.push([Math.cos(a) * reach * t * t, h * Math.sin(t * Math.PI * 0.62) / Math.sin(Math.PI * 0.62), Math.sin(a) * reach * t * t]);
      }
      polyTube(sb, pts, 0.01, 0.005, old ? [0.4, 0.3, 0.22] : [0.38, 0.45, 0.24], 3);
      if (old) continue;
      const leaves = q(lod, 12, 6);
      for (let i = 1; i <= leaves; i += 1) {
        const t = i / (leaves + 1);
        const p = pts[Math.min(4, Math.round(t * 4))];
        const q = add(p, [(r() - 0.5) * 0.1, (r() - 0.5) * 0.1, (r() - 0.5) * 0.1]);
        blade(lb, { base: q, heading: r() * Math.PI * 2, tilt: -0.1 + r() * 0.5, len: (0.15 + r() * 0.05) * grow, wid: 0.13 * grow,
          tile: LEAF.berry, col: [0.9, 1.0, 0.85], cup: 0.2, segs: 1 });
      }
    }
  },

  /** A strawberry row's length: low trifoliate rosettes and their runners. */
  strawberry(lb, sb, r, lod) {
    const near = lod === 'near';
    const grow = lod === 'near' ? 1 : lod === 'mid' ? 1.2 : 1.5;
    const n = q(lod, 5, 3);
    for (let i = 0; i < n; i += 1) {
      const x = -0.45 + (i + r() * 0.5) * (0.9 / n);
      const leaves = q(lod, 6, 4);
      for (let k = 0; k < leaves; k += 1) {
        const a = (k / leaves) * Math.PI * 2 + r();
        const stalk = [x + Math.cos(a) * 0.05, 0.12 + r() * 0.06, Math.sin(a) * 0.05];
        if (near) tube(sb, [x, 0, 0], stalk, 0.003, 0.003, [0.4, 0.42, 0.22], 3);
        for (let j = -1; j <= 1; j += 1) {
          const hd = a + j * 0.95;
          blade(lb, { base: stalk, heading: hd, tilt: 0.05 + r() * 0.3, len: 0.08 * grow, wid: 0.075 * grow,
            tile: LEAF.berry, col: [0.9, 0.95, 0.85], cup: 0.25, segs: 1 });
        }
      }
    }
  },

  /** Asparagus in its summer fern: feathery stems a man's height, the crowns left to grow. */
  asparagus(lb, sb, r, lod) {
    const near = lod === 'near';
    const stems = q(lod, 6, 3);
    for (let s = 0; s < stems; s += 1) {
      const a = r() * Math.PI * 2;
      const h = 1.2 + r() * 0.5;
      const tip = [Math.cos(a) * 0.25, h, Math.sin(a) * 0.25];
      tube(sb, [0, 0, 0], tip, 0.008, 0.003, [0.38, 0.5, 0.22], 3);
      const fronds = q(lod, 6, 3);
      for (let i = 0; i < fronds; i += 1) {
        const f = 0.3 + (i / fronds) * 0.65;
        blade(lb, { base: mul(tip, f), heading: r() * Math.PI * 2, tilt: 0.4 + r() * 0.6, len: 0.38 - f * 0.15,
          wid: 0.3, tile: LEAF.fern, col: [0.92, 1.1, 0.9], cup: 0, segs: 1 });
      }
    }
  },

  /** A clump of sage or thyme: low grey-green mounds. */
  herb(lb, sb, r, lod) {
    const near = lod === 'near';
    const n = q(lod, 14, 6);
    for (let i = 0; i < n; i += 1) {
      const a = r() * Math.PI * 2, d = r() * 0.18;
      blade(lb, { base: [Math.cos(a) * d, 0.03, Math.sin(a) * d], heading: a, tilt: 0.3 + r() * 0.9, len: 0.2 + r() * 0.08,
        wid: 0.12, tile: LEAF.bean, col: [1.1, 1.2, 1.15], cup: 0.2, segs: 1 });
    }
  },
};

/** Each data `kind` and the builder (and its argument) that grows it. */
export const KINDS = {
  corn: ['corn'], pole_bean: ['pole_bean'], cabbage: ['cabbage'], potato: ['potato'],
  muskmelon: ['vine', 'muskmelon'], watermelon: ['vine', 'watermelon'], squash: ['vine', 'squash'],
  cucumber: ['vine', 'cucumber'],
  beet: ['row', 'beet'], carrot: ['row', 'carrot'], parsnip: ['row', 'parsnip'], onion: ['row', 'onion'],
  lettuce: ['row', 'lettuce'],
  currant: ['berry_bush', 'currant'], gooseberry: ['berry_bush', 'gooseberry'], raspberry: ['raspberry'],
  strawberry: ['strawberry'], asparagus: ['asparagus'], herb: ['herb'],
};
const VARIANTS = 3;

/** Grow one variant of one kind at one level: { leaves, solid } geometries. */
export function growTemplate(kind, variant, lod, conf) {
  const [builder, arg] = KINDS[kind];
  const lb = new Buf(), sb = new Buf();
  CROPS[builder](lb, sb, rng(strSeed(`${kind}:${variant}`)), lod, arg);
  return { leaves: lb.count ? lb.geometry(conf) : null, solid: sb.count ? sb.geometry(conf) : null,
    tris: (lb.idx.length + sb.idx.length) / 3 };
}

/* -------------------------------------------------------------------------- */
/* the ground                                                                  */
/* -------------------------------------------------------------------------- */

function pointInPoly(poly, x, y) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i], [xj, yj] = poly[j];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
function distToPoly(poly, x, y) {
  let best = Infinity;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [ax, ay] = poly[j], [bx, by] = poly[i];
    const dx = bx - ax, dy = by - ay;
    const t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy || 1)));
    best = Math.min(best, Math.hypot(x - ax - dx * t, y - ay - dy * t));
  }
  return best;
}

/**
 * A polygon in the garden's frame, draped: a grid of CELL_M cells clipped to it (a cell
 * whose middle is outside is dropped; its edge cells are pulled onto the outline), each
 * vertex on the ground plus `lift`, and `crown` more where it is more than `shoulder`
 * metres in from the edge, so a bed stands as a low raised bed with a sloped side.
 */
function drape(poly, toWorld, groundAt, { lift, crown = 0, shoulder = 0.35, conf, uvScale = 0.5, colorAt = null, cell = CELL_M }) {
  const us = poly.map((p) => p[0]), vs = poly.map((p) => p[1]);
  const u0 = Math.min(...us), u1 = Math.max(...us), v0 = Math.min(...vs), v1 = Math.max(...vs);
  const nu = Math.max(1, Math.ceil((u1 - u0) / cell)), nv = Math.max(1, Math.ceil((v1 - v0) / cell));
  const b = new Buf();
  const ids = new Map();
  const vert = (i, j) => {
    const key = i * 100000 + j;
    if (ids.has(key)) return ids.get(key);
    let u = u0 + (i / nu) * (u1 - u0), v = v0 + (j / nv) * (v1 - v0);
    if (!pointInPoly(poly, u, v)) {
      // pull an outside corner onto the nearest point of the outline
      let best = null, bd = Infinity;
      for (let a = 0, z = poly.length - 1; a < poly.length; z = a++) {
        const [ax, ay] = poly[z], [bx, by] = poly[a];
        const dx = bx - ax, dy = by - ay;
        const t = Math.max(0, Math.min(1, ((u - ax) * dx + (v - ay) * dy) / (dx * dx + dy * dy || 1)));
        const px = ax + dx * t, py = ay + dy * t, d = Math.hypot(u - px, v - py);
        if (d < bd) { bd = d; best = [px, py]; }
      }
      [u, v] = best;
    }
    const d = distToPoly(poly, u, v);
    const k = crown ? Math.min(1, d / shoulder) : 0;
    const [e, n] = toWorld([u, v]);
    const y = groundAt(e, n) + lift + crown * (k * k * (3 - 2 * k));
    const c = colorAt ? colorAt(u, v, d) : [1, 1, 1];
    const id = b.v([e, y, -n], [0, 1, 0], [e * uvScale, n * uvScale], c);
    ids.set(key, id);
    return id;
  };
  for (let i = 0; i < nu; i += 1) {
    for (let j = 0; j < nv; j += 1) {
      const cu = u0 + ((i + 0.5) / nu) * (u1 - u0), cv = v0 + ((j + 0.5) / nv) * (v1 - v0);
      if (!pointInPoly(poly, cu, cv)) continue;
      const a = vert(i, j), bb = vert(i + 1, j), c = vert(i + 1, j + 1), d = vert(i, j + 1);
      b.t(a, bb, c); b.t(a, c, d);
    }
  }
  const g = b.geometry(conf);
  g.computeVertexNormals();
  return g;
}

/* -------------------------------------------------------------------------- */
/* the layer                                                                   */
/* -------------------------------------------------------------------------- */

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/** A garden's frame: plan (u, v) metres to local ENU (e, n). */
function frameOf(g) {
  const [oe, on] = g.frame.origin, [ue, un] = g.frame.u, [ve, vn] = g.frame.v;
  return ([u, v]) => [oe + ue * u + ve * v, on + un * u + vn * v];
}

function bedCard(garden, bed, doc) {
  const crop = doc.crops?.[bed.crop] ?? {};
  const grade = bed.grade ?? 'reconstructed';
  const plantGrade = crop.grade ?? 'reconstructed';
  return {
    id: `garden.${garden.id}.${bed.id}`,
    sidecar: {
      name: `${garden.name}: ${bed.name ?? 'a bed'}`,
      phase: null,
      change_note: crop.note ?? '',
      placement: {
        symbolic_location: garden.where ?? garden.name,
        position_confidence: grade,
        position_sources: bed.sources ?? [],
        position_note: bed.note ?? doc.layout_note ?? '',
      },
      attributes: {
        planting: {
          value: crop.name ?? bed.crop, confidence: plantGrade, sources: crop.sources ?? [],
          note: plantGrade === 'reconstructed' ? `${crop.note ?? ''} Reconstructed: ${doc.liberty ?? ''}`.trim() : (crop.note ?? ''),
        },
      },
      citations: [],
      research_note: `${garden.id}, ${bed.id} in data/gardens/${doc.scene}.json (${doc.ticket}). ${doc.liberty ?? ''}`.trim(),
    },
  };
}

/**
 * @param {object} o
 * @param {URL|string} o.dataBase   the data root (a scene that does not list `gardens` passes none)
 * @param {string} o.sceneId
 * @param {object} o.terrain        surfaceHeight(e, n)
 */
export async function createGardens({
  dataBase, sceneId, terrain, confidence = null, problems = [], detail = 'full', levelAt = null,
  lowSpec = false, onGeometry = null,
} = {}) {
  const group = new THREE.Group();
  group.name = 'gardens';
  const stats = { gardens: 0, beds: 0, plants: 0, near: 0, triangles: 0, drawCalls: 0, detail };
  const out = {
    group, stats, records: [], pickAt: () => null, cardFor: () => null, update() {}, setDetail() {},
    settle() {}, dispose() {},
  };
  if (!dataBase || !terrain) return out;
  let doc;
  try {
    doc = await getJSON(new URL(`gardens/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`gardens: ${err.message} — no garden is planted`);
    return out;
  }
  const gardens = doc.gardens ?? [];
  out.records = gardens;
  stats.gardens = gardens.length;
  if (!gardens.length) return out;
  const groundAt = (e, n) => terrain.surfaceHeight(e, n) + (levelAt?.(e, n) ?? 0);
  const disposers = [];
  // A phone (T-3407 follow-up, 1812 phone memory over its ceiling): the soil laid on a
  // 1.2 m grid, not 0.6, and one grown variant of each crop, turned and sized per plant,
  // not three. Desktop keeps both.
  const cell = lowSpec ? CELL_M * 2 : CELL_M;
  const variants = lowSpec ? 1 : VARIANTS;

  // What build() lays and every later call reads.
  const bedsHit = [];
  const plants = [];
  const geoIds = new Map();
  let leaves = null, solids = null, built = false;

  /** Lay the walks and beds, grow the templates and plant every crop: once. */
  function build() {
    built = true;
    /* ---- the ground: walks, then the beds over them ---- */
    const walkTex = soilCanvas('walk', 7, lowSpec);
    const bedTex = soilCanvas('bed', 9, lowSpec);
    const walkMat = new THREE.MeshStandardMaterial({ map: walkTex, vertexColors: true, roughness: 0.97, metalness: 0,
      polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
    const bedMat = new THREE.MeshStandardMaterial({ map: bedTex, vertexColors: true, roughness: 0.95, metalness: 0,
      polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3 });
    walkMat.name = 'garden-walks'; bedMat.name = 'garden-beds';
    for (const m of [walkMat, bedMat]) confidence?.patch?.(m);
    disposers.push(() => { walkMat.dispose(); bedMat.dispose(); walkTex.dispose(); bedTex.dispose(); });
    for (const g of gardens) {
      const toWorld = frameOf(g);
      const walkConf = CONF[g.walk_grade] ?? 0.5;
      const inset = g.paling_inset_m ?? 0.15;
      const [W, D] = g.size_m;
      const plot = [[inset, inset], [W - inset, inset], [W - inset, D - inset], [inset, D - inset]];
      const walk = new THREE.Mesh(drape(plot, toWorld, groundAt, { lift: SOIL_LIFT.walk, conf: walkConf, uvScale: 0.45, cell,
        // the trodden middle of each walk paler, its edges where the grass hangs on greener
        colorAt: (u, v) => {
          const nearBed = (g.beds ?? []).some((b) => distToPoly(b.poly, u, v) < 0.35);
          return nearBed ? [0.82, 0.9, 0.7] : [1, 1, 1];
        } }), walkMat);
      walk.name = `garden-walks:${g.id}`;
      walk.receiveShadow = true;
      group.add(walk);
      for (const bed of g.beds ?? []) {
        const conf = CONF[bed.grade] ?? 0.5;
        const r = rng(strSeed(bed.id));
        const mesh = new THREE.Mesh(drape(bed.poly, toWorld, groundAt, { lift: SOIL_LIFT.bed, crown: SOIL_LIFT.crown,
          conf, uvScale: 0.5, cell, colorAt: () => tint([1, 1, 1], 0.92 + r() * 0.16) }), bedMat);
        mesh.name = `garden-bed:${g.id}:${bed.id}`;
        mesh.receiveShadow = true;
        group.add(mesh);
        const c = bed.poly.reduce((a, p) => [a[0] + p[0] / bed.poly.length, a[1] + p[1] / bed.poly.length], [0, 0]);
        const [ce, cn] = toWorld(c);
        bedsHit.push({ garden: g, bed, e: ce, n: cn, y: groundAt(ce, cn) + 0.15 });
        stats.beds += 1;
      }
    }

    /* ---- the crops: every plant one instance of its kind's variant ---- */
    const atlas = cropAtlas(lowSpec);
    const leafMat = new THREE.MeshStandardMaterial({ map: atlas, vertexColors: true, roughness: 0.82, metalness: 0,
      side: THREE.DoubleSide, alphaTest: LEAF_CUTOFF });
    leafMat.name = 'garden-leaves';
    const solidMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0 });
    solidMat.name = 'garden-solid';
    confidence?.patch?.(leafMat);
    confidence?.patch?.(solidMat);
    const leafDepth = new THREE.MeshDepthMaterial({ map: atlas, alphaTest: LEAF_CUTOFF, side: THREE.DoubleSide,
      depthPacking: THREE.RGBADepthPacking });
    disposers.push(() => { leafMat.dispose(); solidMat.dispose(); leafDepth.dispose(); });

    // every plant, in world space
    for (const g of gardens) {
      for (const [kind, list] of Object.entries(g.plants ?? {})) {
        if (!KINDS[kind]) { problems.push(`gardens: ${g.id} plants an unknown kind "${kind}"`); continue; }
        const conf = CONF[doc.crops?.[kind]?.grade] ?? 1;
        for (const [e, n, yaw, scale, variant] of list) {
          plants.push({ kind, e, n, y: groundAt(e, n) + SOIL_LIFT.bed, yaw: (yaw * Math.PI) / 180, scale,
            variant: variant % variants, conf });
        }
      }
    }
    stats.plants = plants.length;

    // the templates: per kind, per variant, per level; one grade per kind
    const templates = new Map();
    // A phone builds no near level: its near ring is 8 m (`light`), and the near models are
    // three quarters of the templates' bytes (T-3407 follow-up, 1812 phone memory).
    const lods = lowSpec ? LODS.filter((l) => l !== 'near') : LODS;
    let leafV = 0, leafI = 0, solidV = 0, solidI = 0;
    const kinds = [...new Set(plants.map((p) => p.kind))];
    for (const kind of kinds) {
      const conf = CONF[doc.crops?.[kind]?.grade] ?? 1;
      for (let v = 0; v < variants; v += 1) {
        for (const lod of lods) {
          const t = growTemplate(kind, v, lod, conf);
          templates.set(`${kind}:${v}:${lod}`, t);
          if (t.leaves) { leafV += t.leaves.attributes.position.count; leafI += t.leaves.index.count; }
          if (t.solid) { solidV += t.solid.attributes.position.count; solidI += t.solid.index.count; }
        }
      }
    }
    const n = plants.length;
    leaves = new THREE.BatchedMesh(Math.max(1, n), Math.max(3, leafV), Math.max(3, leafI), leafMat);
    solids = new THREE.BatchedMesh(Math.max(1, n), Math.max(3, solidV), Math.max(3, solidI), solidMat);
    leaves.name = 'garden-crops:leaves'; solids.name = 'garden-crops:solid';
    leaves.customDepthMaterial = leafDepth;
    for (const b of [leaves, solids]) { b.receiveShadow = true; b.perObjectFrustumCulled = true; b.sortObjects = false; }
    for (const [key, t] of templates) {
      geoIds.set(key, {
        leaves: t.leaves ? leaves.addGeometry(t.leaves) : -1,
        solid: t.solid ? solids.addGeometry(t.solid) : -1,
        tris: t.tris,
      });
      t.leaves?.dispose(); t.solid?.dispose();
    }
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3();
    const yAxis = new THREE.Vector3(0, 1, 0);
    for (const pl of plants) {
      const far = geoIds.get(`${pl.kind}:${pl.variant}:far`);
      p.set(pl.e, pl.y, -pl.n);
      q.setFromAxisAngle(yAxis, pl.yaw);
      s.setScalar(pl.scale);
      m4.compose(p, q, s);
      pl.leafId = far.leaves >= 0 ? leaves.addInstance(far.leaves) : -1;
      pl.solidId = far.solid >= 0 ? solids.addInstance(far.solid) : -1;
      if (pl.leafId >= 0) leaves.setMatrixAt(pl.leafId, m4);
      if (pl.solidId >= 0) solids.setMatrixAt(pl.solidId, m4);
      pl.level = 'far';
    }
    group.add(leaves, solids);
    stats.drawCalls = 2 + gardens.length + stats.beds;
    disposers.push(() => { leaves.dispose(); solids.dispose(); });
  }

  /* ---- levels by distance ---- */
  let current = LEVELS[detail] ? detail : 'full';
  let lastEye = null;
  const applyCast = () => {
    if (!built) return;
    const cast = CAST[current] && !lowSpec;
    leaves.castShadow = cast; solids.castShadow = cast;
  };
  // A desktop lays the garden at load. A phone (T-3407 follow-up, 1812 phone memory over its
  // ceiling) lays it the first time the garden comes into the camera's view within its far
  // ring: from the 1812 spawn it is behind the eye, so a phone that never turns to it never
  // pays for it, and one that does pays about a megabyte, uploaded and released at once.
  const ball = new THREE.Sphere();
  {
    const pts = [];
    for (const g of gardens) {
      const toWorld = frameOf(g);
      const [W, D] = g.size_m;
      for (const c of [[0, 0], [W, 0], [W, D], [0, D]]) {
        const [e, n] = toWorld(c);
        pts.push(new THREE.Vector3(e, groundAt(e, n) + 1, -n));
      }
    }
    ball.setFromPoints(pts);
    ball.radius += 3;
  }
  const frustum = new THREE.Frustum(), view = new THREE.Matrix4();
  const comesIntoView = (camera) => {
    if (camera.position.distanceTo(ball.center) - ball.radius > LEVELS[current].far) return false;
    camera.updateMatrixWorld();
    view.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
    return frustum.setFromProjectionMatrix(view).intersectsSphere(ball);
  };
  const ensureBuilt = (camera) => {
    if (built) return true;
    if (!camera || !comesIntoView(camera)) return false;
    build();
    applyCast();
    onGeometry?.(group);
    return true;
  };
  if (!lowSpec) build();
  applyCast();
  const deal = (eye) => {
    if (!built) return;
    const L = LEVELS[current];
    let near = 0, tris = 0;
    for (const pl of plants) {
      const d = Math.hypot(pl.e - eye.x, -pl.n - eye.z);
      const level = d < L.near ? (lowSpec ? 'mid' : 'near') : d < L.mid ? 'mid' : d < L.far ? 'far' : 'none';
      if (level !== pl.level) {
        const ids = level === 'none' ? null : geoIds.get(`${pl.kind}:${pl.variant}:${level}`);
        if (pl.leafId >= 0) {
          leaves.setVisibleAt(pl.leafId, !!ids);
          if (ids && ids.leaves >= 0) leaves.setGeometryIdAt(pl.leafId, ids.leaves);
        }
        if (pl.solidId >= 0) {
          solids.setVisibleAt(pl.solidId, !!ids);
          if (ids && ids.solid >= 0) solids.setGeometryIdAt(pl.solidId, ids.solid);
        }
        pl.level = level;
      }
      if (level === 'near') near += 1;
      if (level !== 'none') tris += geoIds.get(`${pl.kind}:${pl.variant}:${level}`).tris;
    }
    stats.near = near;
    stats.triangles = tris;
  };
  out.update = (dt, camera = null) => {
    if (!camera) return;
    const eye = camera.position;
    if (!built) {
      if (!ensureBuilt(camera)) return;
      lastEye = null;
    }
    if (lastEye && Math.hypot(eye.x - lastEye.x, eye.z - lastEye.z) < STEP_M) return;
    lastEye = eye.clone();
    deal(eye);
  };
  out.settle = (camera) => {
    if (camera && ensureBuilt(camera)) { lastEye = camera.position.clone(); deal(camera.position); }
  };
  out.setDetail = (d) => {
    if (!LEVELS[d] || d === current) return;
    current = d; stats.detail = d;
    applyCast();
    if (lastEye) deal(lastEye);
  };

  /* ---- picks: a bed under the crosshair answers for itself and its crop ---- */
  const ray = new THREE.Raycaster();
  const PICK_M = 60;
  out.pickAt = (ndc, camera) => {
    if (!camera || !group.visible) return null;
    ray.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    const o = ray.ray.origin, d = ray.ray.direction;
    if (Math.abs(d.y) < 1e-6) return null;
    let best = null;
    for (const h of bedsHit) {
      if (Math.hypot(h.e - o.x, -h.n - o.z) > PICK_M) continue;
      const t = (h.y - o.y) / d.y;
      if (!(t > 0)) continue;
      const x = o.x + d.x * t, nn = -(o.z + d.z * t);
      // back into the garden's frame
      const [oe, on] = h.garden.frame.origin, [ue, un] = h.garden.frame.u, [ve, vn] = h.garden.frame.v;
      const de = x - oe, dn = nn - on;
      const u = de * ue + dn * un, v = de * ve + dn * vn;
      if (pointInPoly(h.bed.poly, u, v) && (!best || t < best.distance)) {
        best = { h, distance: t, point: new THREE.Vector3(x, h.y, -nn) };
      }
    }
    if (!best) return null;
    const record = bedCard(best.h.garden, best.h.bed, doc);
    return { id: record.id, record, point: best.point, distance: best.distance };
  };
  out.cardFor = (id) => {
    const m = /^garden\.([^.]+)\.(.+)$/.exec(id ?? '');
    if (!m) return null;
    const g = gardens.find((x) => x.id === m[1]);
    const bed = g?.beds?.find((b) => b.id === m[2]);
    return bed ? bedCard(g, bed, doc) : null;
  };
  out.dispose = () => { for (const f of disposers) f(); };
  return out;
}
